                      return <button type="button" key={option.value} onClick={() => setPaymentMethod(option.value)} aria-pressed={paymentMethod === option.value} className={`flex items-center justify-center gap-2 rounded-2xl border px-3 py-3 text-xs font-black transition ${paymentMethod === option.value ? 'border-blue-700 bg-blue-700 text-white' : 'border-blue-200 bg-white text-blue-800'}`}><Icon className="h-4 w-4" />{option.label}</button>;
                    })}
                  </div>
                  {paymentMethod === 'cliq' && <p className="mt-3 rounded-2xl bg-white p-3 text-[10px] font-bold leading-5 text-slate-600">{storefrontSettings.cliqAlias ? <>حوّل عبر CliQ إلى <strong dir="ltr" className="text-blue-800">{storefrontSettings.cliqAlias}</strong>، وسيؤكد الفريق استلام التحويل قبل التجهيز.</> : 'سيؤكد فريق المتجر بيانات تحويل CliQ واستلامه قبل تجهيز الطلب.'}</p>}
                </div>

                <div className="sm:col-span-2 rounded-3xl border border-emerald-200 bg-emerald-50 p-4">
                  <label className="flex cursor-pointer items-start gap-3"><input type="checkbox" checked={saveCustomerDetails} onChange={(event) => { const enabled = event.target.checked; setSaveCustomerDetails(enabled); if (!enabled) clearSavedGuestCustomer(window.localStorage); }} className="mt-1 h-4 w-4 accent-emerald-600" /><span><span className="flex items-center gap-1.5 text-xs font-black text-emerald-950"><Save className="h-4 w-4" />حفظ بياناتي على هذا الجهاز</span><span className="mt-1 block text-[10px] font-bold leading-5 text-emerald-800/80">اختياري لتعبئة الاسم والهاتف والعنوان تلقائيًا في الطلب القادم.</span><span className="mt-1 block text-[10px] font-bold leading-5 text-emerald-800/80">لا تستخدم هذا الخيار على جهاز مشترك.</span></span></label>
                  {readSavedGuestCustomer(window.localStorage) && <button type="button" onClick={() => { clearSavedGuestCustomer(window.localStorage); setSaveCustomerDetails(false); setForm(EMPTY_GUEST_CHECKOUT_FORM); }} className="mt-3 inline-flex items-center gap-1.5 text-[10px] font-black text-rose-600"><Trash2 className="h-3.5 w-3.5" />مسح البيانات المحفوظة</button>}
                  <button type="button" onClick={onOpenPrivacyPolicy} className="mt-3 block text-[10px] font-black text-blue-700 underline-offset-4 hover:underline">كيف نستخدم ونحمي بياناتك؟ اقرأ سياسة الخصوصية</button>
                </div>

              </div>

              {submitError && (
                <div
                  role="alert"
                  className="mt-5 flex items-start gap-2 rounded-2xl border border-rose-200 bg-rose-50 p-3 text-[11px] font-bold leading-5 text-rose-700"
                >
                  <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
                  <span className="whitespace-pre-line">{checkoutErrorMessage(submitError, pendingAttempt !== null)}</span>
                </div>
              )}
            </div>

            <footer className="border-t border-slate-100 bg-slate-50 p-5 sm:px-7">
              <div className="mb-4 flex items-end justify-between gap-3">
                <div className="flex items-center gap-2 text-[10px] font-bold text-slate-500">
                  <PackageCheck className="h-4 w-4 text-emerald-600" />
                  {paymentMethod === 'cliq' ? 'الدفع عبر CliQ ويُراجع مع الإدارة' : 'الدفع كاش عند الاستلام'}
                </div>
                <div className="text-left">
                  {activePromotionQuote && (
                    <p className="text-[10px] font-bold text-slate-400 line-through">
                      {formatJod(subtotal)}
                    </p>
                  )}
                  {activePromotionQuote && (
                    <p className="text-[10px] font-black text-emerald-600">
                      خصم -
                      {formatJod(
                        activePromotionQuote.discountInMinorUnits
                      )}
                    </p>
                  )}
                  <strong className="text-lg font-black text-slate-950">
                    {formatJod(checkoutTotal)}
                  </strong>
                </div>
              </div>
              <button
                type="submit"
                disabled={
                  isSubmitting ||
                  isApplyingPromotion ||
                  items.length === 0
                  || !storefrontSettings.ordersEnabled
                  || subtotal < storefrontSettings.minimumOrderInMinorUnits
                }
                className="flex w-full items-center justify-center gap-2 rounded-2xl bg-blue-700 px-5 py-4 text-sm font-black text-white shadow-lg shadow-blue-900/20 transition hover:bg-blue-800 disabled:cursor-not-allowed disabled:bg-slate-300 disabled:shadow-none"
              >
                {isSubmitting ? (
                  <>
                    <LoaderCircle className="h-5 w-5 animate-spin" />
                    جارٍ تسجيل الطلب مرة واحدة...
                  </>
                ) : (
                  <>
                    <CheckCircle2 className="h-5 w-5" />
                    مراجعة الطلب قبل الإرسال
                  </>
                )}
              </button>
            </footer>
          </form>
        )}
      </section>
    </div>
  );
}

customer-web/src/index.css.beforeText:
@import 'tailwindcss';

:root {
  font-family: Tahoma, Arial, system-ui, sans-serif;
  color: #0f172a;
  background: #fbf7f0;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  overflow-x: hidden;
}

button,
input {
  font: inherit;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
}

@media (max-width: 767px), (pointer: coarse) {
  input, select, textarea { font-size: max(16px, 1rem) !important; }
  [data-store-header] { padding-top: env(safe-area-inset-top); }
  [role="dialog"] { max-height: 100dvh; padding-top: max(.75rem, env(safe-area-inset-top)); }
}

::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: #eef2f7;
}

::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: #94a3b8;
}

.hero-grid {
  position: absolute;
  inset: 0;
  opacity: 0.08;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.5) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.5) 1px, transparent 1px);
  background-size: 42px 42px;
  mask-image: linear-gradient(to bottom, black, transparent);
}

.hero-orb {
  position: absolute;
  border-radius: 999px;
  filter: blur(70px);
  pointer-events: none;
}

.hero-orb-one {
  top: -100px;
  right: -80px;
  width: 380px;
  height: 380px;
  background: rgba(37, 99, 235, 0.35);
}

.hero-orb-two {
  bottom: -160px;
  left: 4%;
  width: 420px;
  height: 420px;
  background: rgba(249, 115, 22, 0.18);
}

.category-scroll {
  scrollbar-width: thin;
  scrollbar-color: #bfdbfe transparent;
}

.category-scroll::-webkit-scrollbar {
  height: 5px;
}

.category-scroll::-webkit-scrollbar-track {
  background: transparent;
}

.category-scroll::-webkit-scrollbar-thumb {
  background: #bfdbfe;
}

.merchandising-rail {
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  scroll-padding-inline: 0.25rem;
  scrollbar-width: none;
  overscroll-behavior-inline: contain;
  -webkit-overflow-scrolling: touch;
}

.merchandising-rail::-webkit-scrollbar {
  display: none;
}

.merchandising-card {
  scroll-snap-align: start;
  scroll-snap-stop: always;
}

.merchandising-card[data-active='true'] {
  border-color: rgb(191 219 254 / 0.95);
  box-shadow: 0 18px 42px -30px rgb(37 99 235 / 0.55);
}

.category-card-enter {
  animation: category-rise 480ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes category-rise {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.cargo-track {
  bottom: 3px;
  left: 3px;
  right: 3px;
  height: 2px;
  border-radius: 999px;
  opacity: 0.45;
  background: repeating-linear-gradient(
    90deg,
    currentColor 0 4px,
    transparent 4px 7px
  );
}

.cargo-cart-icon {
  left: 50%;
  top: 4px;
  transform: translateX(-50%);
  transition: left 180ms ease, transform 180ms ease;
}

.cargo-box-icon {
  right: 3px;
  top: 2px;
  opacity: 0;
}

.cargo-add-button[data-phase='running'] .cargo-cart-icon {
  left: 3px;
  transform: translateX(0);
  animation: cargo-cart-bump 680ms ease both;
}

.cargo-add-button[data-phase='running'] .cargo-box-icon {
  animation: cargo-box-drop 680ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.cargo-add-button[data-phase='running'] .cargo-track {
  animation: cargo-track-move 420ms linear infinite;
}

.cargo-done-icon {
  left: 50%;
  top: 4px;
  transform: translateX(-50%);
  animation: cargo-done-pop 300ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes cargo-box-drop {
  0% {
    opacity: 0;
    transform: translate(8px, -9px) rotate(10deg) scale(0.85);
  }
  18% {
    opacity: 1;
    transform: translate(0, 0) rotate(0) scale(1);
  }
  72% {
    opacity: 1;
    transform: translate(-23px, 0) rotate(-4deg) scale(0.95);
  }
  100% {
    opacity: 0;
    transform: translate(-27px, 5px) rotate(-8deg) scale(0.55);
  }
}

@keyframes cargo-cart-bump {
  0%,
  65% {
    transform: translateY(0);
  }
  78% {
    transform: translateY(-3px) rotate(-4deg);
  }
  100% {
    transform: translateY(0);
  }
}

@keyframes cargo-track-move {
  to {
    background-position-x: -14px;
  }
}

@keyframes cargo-done-pop {
  from {
    opacity: 0;
    transform: translateX(-50%) scale(0.5) rotate(-16deg);
  }
  to {
    opacity: 1;
    transform: translateX(-50%) scale(1) rotate(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .merchandising-rail {
    scroll-behavior: auto;
  }
}

customer-web/tests/checkout.test.ts.beforeText:
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';
import { STORE_PUBLIC_CONFIG } from '../src/config/store';
import {
  mapGuestOrderReceipt,
  mapGuestPromotionQuote,
} from '../src/services/orders.service';
import { CartItem } from '../src/types/catalog';
import {
  EMPTY_GUEST_CHECKOUT_FORM,
  SAVED_CUSTOMER_STORAGE_KEY,
  SAVED_GUEST_CUSTOMER_TTL_MS,
  PENDING_ORDER_STORAGE_KEY,
  GUEST_ORDER_SESSION_STORAGE_KEY,
  MAX_GUEST_ORDER_LINE_ITEMS,
  MAX_GUEST_DELIVERY_DETAILS_LENGTH,
  buildGuestOrderItems,
  buildGoogleMapsUrl,
  buildWhatsAppOrderMessage,
  buildWhatsAppUrl,
  createOrderFingerprint,
  createPromotionContextKey,
  extractGoogleMapsCoordinates,
  readSavedGuestCustomer,
  saveGuestCustomer,
  clearSavedGuestCustomer,
  readLastGuestOrder,
  saveLastGuestOrder,
  getOrCreateIdempotencyKey,
  buildDeliveryAddress,
  getOrCreateGuestOrderSessionId,
  isSupportedGoogleMapsUrl,
  normalizeJordanPhone,
  normalizePromotionCode,
  validateGuestCheckout,
} from '../src/utils/checkout';

class MemoryStorage {
  private values = new Map<string, string>();

  getItem(key: string) {
    return this.values.get(key) || null;
  }

  setItem(key: string, value: string) {
    this.values.set(key, value);
  }

  removeItem(key: string) {
    this.values.delete(key);
  }
}

const cartItems: CartItem[] = [
  {
    schemaVersion: 2,
    localLineId: 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',
    localRevision: 1,
    commercialLineKind: 'legacy_single_sku_parcel',
    productId: '11111111-1111-4111-8111-111111111111',
    sku: 'NWS-1001',
    nameAr: 'بيبسي',
    imageUrl: '',
    saleUnitNameAr: 'كرتونة',
    unitsPerSalePackage: 12,
    unitPriceInMinorUnits: 5400,
    quantity: 2,
    maxAvailablePackages: 3,
  },
];

const validForm = {
  ...EMPTY_GUEST_CHECKOUT_FORM,
  fullName: 'محمد أحمد',
  phone: '0791234567',
  area: 'الحي الشرقي',
  street: 'شارع الجامعة بجانب الصيدلية',
};

test('Jordan phone formats resolve to one guest customer identity', () => {
  assert.equal(normalizeJordanPhone('0791234567'), '0791234567');
  assert.equal(normalizeJordanPhone('+962 79 123 4567'), '0791234567');
  assert.equal(normalizeJordanPhone('962791234567'), '0791234567');
  assert.equal(normalizeJordanPhone('791234567'), '0791234567');
  assert.equal(normalizeJordanPhone('061234567'), null);
});

test('guest checkout requires identity and a structured deliverable address', () => {
  assert.deepEqual(validateGuestCheckout(validForm), {});
  const errors = validateGuestCheckout({
    ...validForm,
    fullName: '',
    phone: '123',
    area: '',
    street: '',
  });
  assert.ok(errors.fullName);
  assert.ok(errors.phone);
  assert.ok(errors.area);
  assert.equal(errors.street, 'اكتب تفاصيل كافية للوصول إلى عنوان التوصيل.');
});

test('delivery details use the RPC length limit before the request is sent', () => {
  assert.equal(MAX_GUEST_DELIVERY_DETAILS_LENGTH, 300);
  const baseAddressLength = buildDeliveryAddress({...validForm, street: ''}).length;
  const maxOptionalDetailsLength = MAX_GUEST_DELIVERY_DETAILS_LENGTH - baseAddressLength - 3;
  assert.deepEqual(
    validateGuestCheckout({
      ...validForm,
      street: 'أ'.repeat(maxOptionalDetailsLength),
    }),
    {}
  );
  assert.match(
    validateGuestCheckout({
      ...validForm,
      street: 'أ'.repeat(maxOptionalDetailsLength + 1),
    }).street || '',
    /300/
  );
});

test('structured address remains canonical while V2 requires delivery details', () => {
  const withoutDetails = {...validForm, street: ''};
  assert.equal(buildDeliveryAddress(withoutDetails), 'إربد - الرمثا - الحي الشرقي');
  assert.equal(
    validateGuestCheckout(withoutDetails).street,
    'اكتب تفاصيل كافية للوصول إلى عنوان التوصيل.'
  );
  assert.equal(buildDeliveryAddress({...withoutDetails, street: 'بناية 12، اتصل قبل الوصول'}), 'إربد - الرمثا - الحي الشرقي - بناية 12، اتصل قبل الوصول');
});

test('current GPS coordinates produce a stable Google Maps link', () => {
  assert.equal(
    buildGoogleMapsUrl(32.55812, 36.008742),
    'https://www.google.com/maps?q=32.558120,36.008742'
  );
  assert.throws(() => buildGoogleMapsUrl(120, 36), /إحداثيات/);
});

test('delivery location accepts Google Maps sharing links and rejects arbitrary URLs', () => {
  assert.equal(
    isSupportedGoogleMapsUrl('https://maps.app.goo.gl/AbCdEf123'),
    true
  );
  assert.equal(
    isSupportedGoogleMapsUrl('https://www.google.com/maps?q=32.55,36.00'),
    true
  );
  assert.equal(
    isSupportedGoogleMapsUrl('https://maps.google.com/?q=32.55,36.00'),
    true
  );
  assert.equal(isSupportedGoogleMapsUrl('https://example.com/maps'), false);

  assert.ok(
    validateGuestCheckout({
      ...validForm,
      googleMapsUrl: 'https://example.com/maps',
    }).googleMapsUrl
  );
});

test('direct Google Maps links expose exact coordinates for confirmed delivery', () => {
  assert.deepEqual(
    extractGoogleMapsCoordinates(
      'https://maps.google.com/?q=32.558120,36.008742'
    ),
    { latitude: 32.55812, longitude: 36.008742 }
  );
  assert.deepEqual(
    extractGoogleMapsCoordinates(
      'https://www.google.com/maps/place/Ramtha/@32.558120,36.008742,16z'
    ),
    { latitude: 32.55812, longitude: 36.008742 }
  );
  assert.equal(
    extractGoogleMapsCoordinates('https://maps.app.goo.gl/AbCdEf123'),
    null
  );
});

test('guest order sends wholesale package counts only', () => {
  assert.deepEqual(buildGuestOrderItems(cartItems), [
    {
      product_id: '11111111-1111-4111-8111-111111111111',
      quantity: 2,
    },
  ]);
});

test('guest checkout exposes the same 50-line-item limit as the server gateway', () => {
  assert.equal(MAX_GUEST_ORDER_LINE_ITEMS, 50);
});

test('the same pending checkout reuses one idempotency key', () => {
  const storage = new MemoryStorage();
  const fingerprint = createOrderFingerprint(validForm, cartItems);
  const firstKey = getOrCreateIdempotencyKey(
    storage as unknown as Storage,
    fingerprint,
    1000
  );
  const secondKey = getOrCreateIdempotencyKey(
    storage as unknown as Storage,
    fingerprint,
    2000
  );
  assert.equal(firstKey, secondKey);
  assert.match(
    storage.getItem(PENDING_ORDER_STORAGE_KEY) || '',
    /"fingerprint":"[0-9a-f]{8}"/
  );
  assert.doesNotMatch(
    storage.getItem(PENDING_ORDER_STORAGE_KEY) || '',
    /محمد|0791234567/
  );
});

test('guest order session ID is opaque, stable per session and contains no customer data', () => {
  const storage = new MemoryStorage();
  const first = getOrCreateGuestOrderSessionId(
    storage as unknown as Storage
  );
  const second = getOrCreateGuestOrderSessionId(
    storage as unknown as Storage
  );
  assert.equal(first, second);
  assert.match(first, /^[0-9a-f-]{36}$/i);
  assert.equal(storage.getItem(GUEST_ORDER_SESSION_STORAGE_KEY), first);
  assert.doesNotMatch(first, /محمد|0791234567/);
});

test('payment choice changes the protected order fingerprint', () => {
  assert.notEqual(
    createOrderFingerprint(validForm, cartItems, '', 'cash_on_delivery'),
    createOrderFingerprint(validForm, cartItems, '', 'cliq')
  );
});

test('delivery zone changes the protected order fingerprint', () => {
  assert.notEqual(
    createOrderFingerprint(validForm, cartItems, '', 'cash_on_delivery', 'inside_ramtha'),
    createOrderFingerprint(validForm, cartItems, '', 'cash_on_delivery', 'outside_ramtha')
  );
});

test('saved customer data and last order stay optional on this device', () => {
  const storage = new MemoryStorage();
  saveGuestCustomer(storage as unknown as Storage, validForm);
  assert.equal(readSavedGuestCustomer(storage as unknown as Storage)?.phone, '0791234567');
  clearSavedGuestCustomer(storage as unknown as Storage);
  assert.equal(readSavedGuestCustomer(storage as unknown as Storage), null);

  saveLastGuestOrder(storage as unknown as Storage, 'ORD-2026-001', cartItems);
  assert.equal(readLastGuestOrder(storage as unknown as Storage)?.items[0].quantity, 2);
});

test('saved customer details expire after thirty days and are removed', () => {
  const storage = new MemoryStorage();
  const savedAt = 1_700_000_000_000;
  saveGuestCustomer(storage as unknown as Storage, validForm, savedAt);

  const raw = storage.getItem(SAVED_CUSTOMER_STORAGE_KEY);
  assert.ok(raw);
  const persisted = JSON.parse(raw);
  assert.equal(persisted.version, 3);
  assert.equal(persisted.expiresAt, savedAt + SAVED_GUEST_CUSTOMER_TTL_MS);
  assert.equal('customerNotes' in persisted.customer, false);
  assert.equal(
    readSavedGuestCustomer(storage as unknown as Storage, savedAt + SAVED_GUEST_CUSTOMER_TTL_MS - 1)?.phone,
    validForm.phone,
  );
  assert.equal(
    readSavedGuestCustomer(storage as unknown as Storage, savedAt + SAVED_GUEST_CUSTOMER_TTL_MS),
    null,
  );
  assert.equal(storage.getItem(SAVED_CUSTOMER_STORAGE_KEY), null);
});

test('version two saved customer records migrate locally without order notes', () => {
  const storage = new MemoryStorage();
  const savedAt = 1_700_000_000_000;
  storage.setItem(SAVED_CUSTOMER_STORAGE_KEY, JSON.stringify({
    version: 2,
    customer: { ...validForm, customerNotes: 'ملاحظة لطلب قديم' },
    savedAt,
    expiresAt: savedAt + SAVED_GUEST_CUSTOMER_TTL_MS,
  }));

  const restored = readSavedGuestCustomer(storage as unknown as Storage, savedAt + 1);
  assert.equal(restored?.phone, validForm.phone);
  assert.equal(restored?.customerNotes, '');

  const migrated = JSON.parse(storage.getItem(SAVED_CUSTOMER_STORAGE_KEY) ?? '{}');
  assert.equal(migrated.version, 3);
  assert.equal('customerNotes' in migrated.customer, false);
});

test('legacy or malformed saved customer storage fails closed and is removed', () => {
  const storage = new MemoryStorage();
  storage.setItem(SAVED_CUSTOMER_STORAGE_KEY, JSON.stringify({ version: 1, customer: validForm, savedAt: Date.now() }));
  assert.equal(readSavedGuestCustomer(storage as unknown as Storage), null);
  assert.equal(storage.getItem(SAVED_CUSTOMER_STORAGE_KEY), null);

  storage.setItem(SAVED_CUSTOMER_STORAGE_KEY, '{not-json');
  assert.equal(readSavedGuestCustomer(storage as unknown as Storage), null);
  assert.equal(storage.getItem(SAVED_CUSTOMER_STORAGE_KEY), null);
});

test('saved customer storage stays absent when consent is revoked or never given', () => {
  const storage = new MemoryStorage();
  assert.equal(storage.getItem(SAVED_CUSTOMER_STORAGE_KEY), null);
  saveGuestCustomer(storage as unknown as Storage, validForm);
  clearSavedGuestCustomer(storage as unknown as Storage);
  assert.equal(storage.getItem(SAVED_CUSTOMER_STORAGE_KEY), null);
});

test('successful RPC data maps to a stable order receipt', () => {
  const receipt = mapGuestOrderReceipt({
    success: true,
    order_id: 'order-id',
    order_number: 'ORD-2026-001',
    customer_id: 'customer-id',
    customer_address_id: 'address-id',
    customer_reused: true,
    idempotent_replay: false,
    subtotal: 10800,
    total: 10800,
    discount: 0,
    delivery_fee: 2000,
    delivery_zone: 'outside_ramtha',
    status: 'new',
    message: 'تم إنشاء الطلب',
  });
  assert.equal(receipt.orderNumber, 'ORD-2026-001');
  assert.equal(receipt.totalInMinorUnits, 10800);
  assert.equal(receipt.customerReused, true);
  assert.equal(receipt.deliveryFeeInMinorUnits, 2000);
  assert.equal(receipt.deliveryZone, 'outside_ramtha');
});

test('promotion preview uses the server-calculated discount and total', () => {
  const quote = mapGuestPromotionQuote({
    success: true,
    promotion_code_id: 'promotion-id',
    code: 'WELCOME10',
    description: 'خصم الافتتاح',
    subtotal: 10800,
    discount: 1080,
    total: 9720,
  });
  assert.equal(quote.code, 'WELCOME10');
  assert.equal(quote.discountInMinorUnits, 1080);
  assert.equal(quote.totalInMinorUnits, 9720);
  assert.equal(normalizePromotionCode(' welcome10 '), 'WELCOME10');
});

test('promotion quote context changes with phone or cart quantity', () => {
  const first = createPromotionContextKey(validForm.phone, cartItems);
