 const counters=new Map<string,Counter>(),writes:Record<string,unknown>[]=[];let reads=0,lowReads=0;
 const current=(id:string)=>counters.get(id)??{enabled:false,quantity:0,threshold:0,revision:0,everEnabled:false};
