    parcelReads.push(route.request().postDataJSON());return route.fulfill({json: {options: []}});
  });
  await page.goto(url);
  await expect(page.getByRole('button', {name: 'بطاقة 💳'})).toHaveCount(0);
  const card = page.locator(`[data-pos-product-card="${productId}"]`);
