src/features/accounts/RecordCustomerPaym.beforeText:
import React, { useEffect, useMemo, useRef, useState, useId } from 'react';
import { Banknote, CheckCircle2, ChevronLeft, ChevronRight, Loader2, ReceiptText, Search } from 'lucide-react';
import { CURRENCY } from '../../constants';
import {
  CustomerOutstandingOrder,
  fetchCustomerOutstandingOrders,
  recordCustomerOrderPayment,
} from '../../services/supabase/customerAccounts.service';
import { useAppStoreActions } from '../../stores/useAppStore';
import {businessErrorMessage} from '../../utils/businessError';

interface RecordCustomerPaymentModalProps {
  initialOrder?: CustomerOutstandingOrder | null;
  onClose: () => void;
  onSuccess?: () => void;
}

const createPaymentIdempotencyKey = () =>
  typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function'
    ? crypto.randomUUID()
    : `customer-payment-${Date.now()}-${Math.random().toString(36).slice(2)}`;

export const RecordCustomerPaymentModal: React.FC<
  RecordCustomerPaymentModalProps
> = ({ initialOrder, onClose, onSuccess }) => {
  const fieldId = useId();
  const { setToast } = useAppStoreActions();
  const [orders, setOrders] = useState<CustomerOutstandingOrder[]>([]);
  const [orderId, setOrderId] = useState(initialOrder?.id || '');
  const [amount, setAmount] = useState(
    initialOrder ? String(initialOrder.amountDue) : ''
  );
  const [paymentMethod, setPaymentMethod] = useState<
    'cash' | 'cliq'
  >('cash');
  const [referenceNumber, setReferenceNumber] = useState('');
  const [notes, setNotes] = useState('');
  const [loading, setLoading] = useState(true);
  const [hasLoaded, setHasLoaded] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [orderSearch, setOrderSearch] = useState('');
  const [orderPage, setOrderPage] = useState(1);
  const [orderTotalPages, setOrderTotalPages] = useState(1);
  const paymentIdempotencyKey = useRef(createPaymentIdempotencyKey());

  useEffect(() => {
    let mounted = true;
    setLoading(true);
    setError(null);
    fetchCustomerOutstandingOrders({
      page: orderPage,
      pageSize: 25,
      search: initialOrder ? undefined : orderSearch,
    }).then((result) => {
      if (!mounted) return;
      if (result.success) {
        setOrders(result.orders);
        setOrderTotalPages(result.totalPages);
        if (!initialOrder && result.orders[0]) {
          setOrderId(result.orders[0].id);
          setAmount(String(result.orders[0].amountDue));
        }
      } else {
        setError(businessErrorMessage(result.error || 'تعذر تحميل الذمم.'));
      }
    }).catch(error => {
      if (mounted) setError(businessErrorMessage(error));
    }).finally(() => {
      if (mounted) { setLoading(false); setHasLoaded(true); }
    });
    return () => { mounted = false; };
  }, [initialOrder, orderPage, orderSearch]);

  const selectedOrder = useMemo(
    () =>
      orders.find((order) => order.id === orderId) ||
      (initialOrder?.id === orderId ? initialOrder : null),
    [initialOrder, orderId, orders]
  );

  const handleOrderChange = (nextOrderId: string) => {
    setOrderId(nextOrderId);
    const order = orders.find((item) => item.id === nextOrderId);
    setAmount(order ? String(order.amountDue) : '');
  };

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    const numericAmount = Number(amount);
    if (!selectedOrder) {
      setError('اختر طلبًا عليه مبلغ مستحق.');
      return;
    }
    if (paymentMethod === 'cliq' && !referenceNumber.trim()) {
      setError('رقم مرجع CliQ مطلوب لتسجيل الدفعة.');
      return;
    }
    if (
      !Number.isFinite(numericAmount) ||
      numericAmount <= 0 ||
      numericAmount > selectedOrder.amountDue
    ) {
      setError(
        `الدفعة يجب أن تكون بين 0.001 و${selectedOrder.amountDue.toFixed(
          3
        )} ${CURRENCY}.`
      );
      return;
    }

    setSaving(true);
    try {
      setError(null);
      const result = await recordCustomerOrderPayment({
        orderId: selectedOrder.id,
        amount: numericAmount,
        paymentMethod,
        referenceNumber: referenceNumber.trim(),
        notes: notes.trim(),
        idempotencyKey: paymentIdempotencyKey.current,
      });


      if (!result.success) {
        setError(businessErrorMessage(result.error || 'تعذر تسجيل الدفعة.'));
        return;
      }

      setToast(
        `تم حفظ سند القبض ${result.paymentNumber || ''} بنجاح.`,
        'success'
      );
      onSuccess?.();
      onClose();

    } finally {
      setSaving(false);
    }
  };

  if (loading && !hasLoaded) {
    return (
      <div className="flex items-center justify-center gap-2 py-10 text-xs font-bold text-nw-muted">
        <Loader2 className="h-5 w-5 animate-spin text-nw-ok" />
        جاري تحميل الذمم الحقيقية...
      </div>
    );
  }

  if (!loading && !error && orders.length === 0 && !initialOrder && !orderSearch.trim()) {
    return (
      <div className="rounded-2xl border border-nw-ok bg-nw-ok-bg p-6 text-center">
        <CheckCircle2 className="mx-auto mb-2 h-9 w-9 text-nw-ok" />
        <h3 className="text-sm font-black text-nw-text">{orderSearch.trim() ? 'لا توجد نتائج لهذا البحث' : 'لا توجد ذمم مستحقة'}</h3>
        <p className="mt-1 text-[11px] text-nw-muted">
          {orderSearch.trim() ? 'غيّر رقم الطلب أو اسم العميل أو الهاتف، أو امسح البحث.' : 'لا توجد مبالغ مستحقة ضمن الطلبات المتاحة لك.'}
        </p>
        {orderSearch.trim() && <button type="button" onClick={() => { setOrderSearch(''); setOrderPage(1); }} className="mt-3 rounded-xl border border-nw-border px-3 py-2 text-nw-text">مسح البحث</button>}
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} aria-busy={saving} className="space-y-3 text-xs">
      {loading && <p className="text-nw-muted">جاري تحديث الذمم...</p>}
      {!loading && !error && orders.length === 0 && orderSearch.trim() && (
        <div className="rounded-xl border border-nw-border p-3">
          <h3 className="font-bold">لا توجد نتائج لهذا البحث</h3>
          <p>غيّر رقم الطلب أو اسم العميل أو الهاتف، أو امسح البحث.</p>
          <button type="button" onClick={() => {setOrderSearch(''); setOrderPage(1);}} className="mt-2 underline">مسح البحث</button>
        </div>
      )}
      {error && (
        <div className="rounded-xl border border-nw-bad bg-nw-bad-bg p-3 text-nw-bad">
          {error}
        </div>
      )}

      <div>
        {!initialOrder && (
          <label className="mb-2 flex items-center gap-2 rounded-xl border border-nw-border bg-nw-surface-2 px-3 py-2 text-nw-muted">
            <Search className="h-3.5 w-3.5" />
            <input
              aria-label="البحث عن طلب أو عميل أو هاتف"
              value={orderSearch}
              onChange={(event) => {
                setOrderSearch(event.target.value);
                setOrderPage(1);
              }}
              placeholder="ابحث برقم الطلب أو العميل أو الهاتف"
              className="w-full bg-transparent text-xs text-nw-text outline-none placeholder:text-nw-muted"
            />
          </label>
        )}
        <label htmlFor={`${fieldId}-order`} className="mb-1 block font-bold text-nw-text">
          الطلب والعميل *
        </label>
        <select
          id={`${fieldId}-order`}
          value={orderId}
          onChange={(event) => handleOrderChange(event.target.value)}
          disabled={Boolean(initialOrder)}
          className="w-full rounded-xl border border-nw-border bg-nw-surface-2 p-2.5 text-nw-text disabled:opacity-70"
        >
          <option value="">اختر الطلب</option>
          {(initialOrder
            ? [initialOrder]
            : orders
          ).map((order) => (
            <option key={order.id} value={order.id}>
              {order.orderNumber} — {order.customerName} — متبقي{' '}
              {order.amountDue.toFixed(3)} {CURRENCY}
            </option>
          ))}
        </select>
        {!initialOrder && orderTotalPages > 1 && (
          <div className="mt-2 flex items-center justify-between text-[10px] text-nw-muted">
            <button type="button" onClick={() => setOrderPage((current) => Math.max(1, current - 1))} disabled={orderPage <= 1} className="rounded-lg border border-nw-border px-2 py-1 disabled:opacity-40">
              <ChevronRight className="inline h-3 w-3" /> السابق
            </button>
            <span>{orderPage} / {orderTotalPages}</span>
            <button type="button" onClick={() => setOrderPage((current) => Math.min(orderTotalPages, current + 1))} disabled={orderPage >= orderTotalPages} className="rounded-lg border border-nw-border px-2 py-1 disabled:opacity-40">
              التالي <ChevronLeft className="inline h-3 w-3" />
            </button>
          </div>
        )}
      </div>

      {selectedOrder && (
        <div className="grid grid-cols-3 gap-2 rounded-2xl border border-nw-border bg-nw-surface-2 p-3 text-center">
          <div>
            <span className="block text-[10px] text-nw-muted">الإجمالي</span>
            <strong className="text-nw-text">
              {selectedOrder.totalAmount.toFixed(3)}
            </strong>
          </div>
          <div>
            <span className="block text-[10px] text-nw-muted">المدفوع</span>
            <strong className="text-nw-ok">
              {selectedOrder.amountPaid.toFixed(3)}
            </strong>
          </div>
          <div>
            <span className="block text-[10px] text-nw-muted">المتبقي</span>
            <strong className="text-nw-bad">
              {selectedOrder.amountDue.toFixed(3)}
            </strong>
          </div>
        </div>
      )}

      <div className="grid grid-cols-2 gap-2">
        <div>
          <label htmlFor={`${fieldId}-amount`} className="mb-1 block font-bold text-nw-text">
            مبلغ الدفعة ({CURRENCY}) *
          </label>
          <input inputMode="decimal" enterKeyHint="next"
            id={`${fieldId}-amount`}
            type="number"
            min="0.001"
            step="0.001"
            max={selectedOrder?.amountDue}
            value={amount}
            onChange={(event) => setAmount(event.target.value)}
            className="w-full rounded-xl border border-nw-border bg-nw-surface-2 p-2.5 font-bold text-nw-ok"
            required
          />
        </div>
        <div>
          <label htmlFor={`${fieldId}-method`} className="mb-1 block font-bold text-nw-text">
            طريقة الدفع *
          </label>
          <select
            id={`${fieldId}-method`}
            value={paymentMethod}
            onChange={(event) =>
              setPaymentMethod(event.target.value as typeof paymentMethod)
            }
            className="w-full rounded-xl border border-nw-border bg-nw-surface-2 p-2.5 text-nw-text"
          >
            <option value="cash">نقدي</option>
            <option value="cliq">CliQ</option>
          </select>
        </div>
      </div>

      <div>
        <label htmlFor={`${fieldId}-reference`} className="mb-1 block font-bold text-nw-text">
          {paymentMethod === 'cliq' ? 'رقم مرجع CliQ *' : 'رقم المرجع (اختياري)'}
        </label>
        <input
          id={`${fieldId}-reference`}
          value={referenceNumber}
          onChange={(event) => setReferenceNumber(event.target.value)}
          placeholder={paymentMethod === 'cliq' ? 'رقم مرجع CliQ' : 'مرجع داخلي إن وجد'}
          required={paymentMethod === 'cliq'}
          className="w-full rounded-xl border border-nw-border bg-nw-surface-2 p-2.5 text-nw-text"
        />
      </div>

      <div>
        <label htmlFor={`${fieldId}-notes`} className="mb-1 block font-bold text-nw-text">
          ملاحظات (اختياري)
        </label>
        <textarea
          id={`${fieldId}-notes`}
          rows={2}
          value={notes}
          onChange={(event) => setNotes(event.target.value)}
          className="w-full resize-none rounded-xl border border-nw-border bg-nw-surface-2 p-2.5 text-nw-text"
        />
      </div>

      <button
        type="submit"
        disabled={saving || loading || !selectedOrder}
        className="flex min-h-12 w-full items-center justify-center gap-2 rounded-2xl bg-nw-accent py-3 font-bold text-nw-on-accent transition hover:brightness-105 disabled:opacity-60"
      >
        {saving ? (
          <Loader2 className="h-4 w-4 animate-spin" />
        ) : (
          <ReceiptText className="h-4 w-4" />
        )}
        {saving ? 'جاري حفظ السند...' : 'حفظ سند القبض وتحديث الذمة'}
      </button>

      <p className="flex items-center gap-1 text-[10px] text-nw-muted">
        <Banknote className="h-3 w-3" />
        تُربط الدفعة بالطلب وتُحدّث الذمة تلقائيًا من قاعدة البيانات.
      </p>
    </form>
  );
};

src/features/crm/CustomerCollectionModal.beforeText:
import React, { useCallback, useEffect, useId, useState } from 'react';
import { CheckCircle2, Loader2, RotateCcw } from 'lucide-react';
import { FormFields, StatusBadge, UiButton, formatMinorUnits, formatUiDate } from '../../components/ui';
import { useAppStoreActions, useAppStoreSelector } from '../../stores/useAppStore';
import { parseJodToMinor } from '../goLive/goLiveImport';
import {ChequeRegistrationForm} from '../cheques/ChequeRegistrationForm';
import {
  collectCustomerBalance, fetchCustomerCollections, newIdempotencyKey, previewCustomerCollection, reverseCustomerCollection,
  type CollectionMethod, type CollectionOperation, type CollectionPreview,
} from '../../services/supabase/goLive.service';

interface CustomerCollectionModalProps {
  customerId: string;
  onClose: () => void;
  onSuccess: () => void;
}

const Money: React.FC<{ minor: number }> = ({ minor }) => (
  <span className="whitespace-nowrap"><bdi dir="ltr" className="nw-num">{formatMinorUnits(minor)}</bdi> <span className="text-xs text-nw-muted">د.أ</span></span>
);
const methodLabel: Readonly<Record<string, string>> = { cash: 'كاش', cliq: 'CliQ', bank_transfer: 'تحويل بنكي',cheque:'شيك مؤجل' };
const fieldClass = 'h-11 w-full rounded-xl border border-nw-border bg-nw-surface px-3 text-sm text-nw-text';
const errorText = (error: unknown) => (error instanceof Error ? error.message : 'تعذر تنفيذ العملية.');

/**
 * «تحصيل من الزبون»: one lump sum, allocated by the database oldest-first —
 * opening debts first by their original date, then open orders — and shown
 * as a preview before saving. Order parts use the existing order payment path.
 */
export const CustomerCollectionModal: React.FC<CustomerCollectionModalProps> = ({ customerId, onClose, onSuccess }) => {
  const ids = { amount: useId(), method: useId(), reference: useId(), notes: useId(), reason: useId() };
  const { setToast } = useAppStoreActions();
  const branchId = useAppStoreSelector(state => state.activeBranch?.id ?? null);
  const isCashier = useAppStoreSelector(state => state.currentUser.role === 'Cashier');
  const [amount, setAmount] = useState('');
  const [method, setMethod] = useState<CollectionMethod>('cash');
  const [reference, setReference] = useState('');
  const [notes, setNotes] = useState('');
  const [preview, setPreview] = useState<(CollectionPreview & { minor: number; method: CollectionMethod }) | null>(null);
  const [key, setKey] = useState(() => newIdempotencyKey('collect'));
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [history, setHistory] = useState<CollectionOperation[]>([]);
  const [reversing, setReversing] = useState<CollectionOperation | null>(null);
  const [reason, setReason] = useState('');
  const [receivingCheque,setReceivingCheque]=useState(false);

  const loadHistory = useCallback(async () => {
    try { setHistory(await fetchCustomerCollections(customerId)); } catch { setHistory([]); }
  }, [customerId]);
  useEffect(() => { void loadHistory(); }, [loadHistory]);

  const minor = parseJodToMinor(amount);
  const previewIsCurrent = preview !== null && minor !== null && preview.minor === Number(minor) && preview.method === method;

  const runPreview = async () => {
    setError('');
    if (!minor || minor === '0') { setError('أدخل مبلغاً أكبر من صفر بثلاث منازل عشرية كحد أقصى.'); return; }
    setBusy(true);
    try {
      const result = await previewCustomerCollection(customerId, Number(minor));
      setPreview({ ...result, minor: Number(minor), method });
      setKey(newIdempotencyKey('collect'));
      if (result.exceedsBalance) setError('المبلغ أكبر من مجموع دين العميل؛ خفّض المبلغ.');
    } catch (e) { setError(errorText(e)); } finally { setBusy(false); }
  };

  const save = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!previewIsCurrent || !preview || preview.exceedsBalance) { await runPreview(); return; }
    if (method === 'cliq' && !reference.trim()) { setError('رقم مرجع CliQ مطلوب.'); return; }
    setBusy(true); setError('');
    try {
      const operation = await collectCustomerBalance({ customerId, amountInMinorUnits: preview.minor, method,
        branchId, reference, notes, idempotencyKey: key });
      setToast(`تم التحصيل ${operation.operationNumber}`, 'success');
      onSuccess(); onClose();
    } catch (e) { setError(errorText(e)); } finally { setBusy(false); }
  };

  const reverse = async () => {
    if (!reversing) return;
    setBusy(true); setError('');
    try {
      await reverseCustomerCollection(reversing.operationId, reason);
      setReversing(null); setReason(''); await loadHistory(); onSuccess();
    } catch (e) { setError(errorText(e)); } finally { setBusy(false); }
  };

  if(receivingCheque)return <ChequeRegistrationForm direction="incoming" partyId={customerId} parties={[{id:customerId,name:'العميل المحدد للتحصيل'}]}
    branchId={branchId} onClose={()=>setReceivingCheque(false)} onSaved={()=>{onSuccess();onClose();}} />;
  return (
    <div dir="rtl" className="space-y-4" data-testid="customer-collection">
      <UiButton disabled={busy} onClick={()=>setReceivingCheque(true)}>استلام شيك مؤجل</UiButton>
      <FormFields>
        <form className="grid gap-3 sm:grid-cols-2" onSubmit={event => void save(event)} aria-busy={busy}>
          <div>
            <label htmlFor={ids.amount} className="mb-1 block text-[13px] font-semibold">المبلغ المقبوض (د.أ) *</label>
            <input enterKeyHint="next" id={ids.amount} className={fieldClass} inputMode="decimal" dir="ltr" value={amount}
              onChange={event => { setAmount(event.target.value); }} placeholder="0.000" required />
          </div>
          <div>
            <label htmlFor={ids.method} className="mb-1 block text-[13px] font-semibold">طريقة الدفع *</label>
            <select id={ids.method} className={fieldClass} value={method} onChange={event => setMethod(event.target.value as CollectionMethod)}>
              <option value="cash">كاش — يدخل درج الوردية المفتوحة</option>
              <option value="cliq">CliQ — على الوردية خارج الدرج</option>
              <option value="bank_transfer">تحويل بنكي — بلا وردية</option>
            </select>
          </div>
          {method !== 'cash' && (
            <div>
              <label htmlFor={ids.reference} className="mb-1 block text-[13px] font-semibold">{method === 'cliq' ? 'رقم مرجع CliQ *' : 'رقم مرجع التحويل'}</label>
              <input id={ids.reference} className={fieldClass} dir="ltr" maxLength={100} value={reference} onChange={event => setReference(event.target.value)} />
            </div>
          )}
          <div className={method === 'cash' ? 'sm:col-span-2' : ''}>
            <label htmlFor={ids.notes} className="mb-1 block text-[13px] font-semibold">ملاحظات (اختياري)</label>
            <input id={ids.notes} className={fieldClass} maxLength={300} value={notes} onChange={event => setNotes(event.target.value)} />
          </div>

          {preview && (
            <div className="sm:col-span-2 space-y-2 rounded-2xl border border-nw-border bg-nw-surface-2 p-3" data-testid="customer-collection-preview">
              <p className="m-0 text-sm font-bold">{`معاينة التوزيع من الأقدم (${previewIsCurrent ? 'محدّثة' : 'غيّرت المبلغ أو الطريقة؛ أعد المعاينة'})`}</p>
              <p className="m-0 text-[13px] text-nw-muted">مجموع الدين <Money minor={preview.totalOutstandingInMinorUnits} /> · ديون سابقة <Money minor={preview.openingOutstandingInMinorUnits} /> · طلبات <Money minor={preview.ordersOutstandingInMinorUnits} /></p>
              {Boolean(preview.compensationOutstandingInMinorUnits)&&<p className="m-0 text-sm text-nw-muted">قيود شيكات <Money minor={preview.compensationOutstandingInMinorUnits??0} /></p>}
              <ul className="m-0 list-none space-y-1 p-0">
                {preview.parts.filter(part => part.allocateInMinorUnits > 0).map(part => (
                  <li key={part.id} className="flex flex-wrap items-center justify-between gap-2 rounded-xl bg-nw-surface p-2 text-[13px]">
                    <span className="min-w-0">
                      <StatusBadge tone={part.kind === 'opening' ? 'warn' : 'info'}>{part.kind === 'opening' ? 'رصيد سابق قبل النظام' : part.kind === 'compensation' ? 'قيد تعويض شيك' : 'طلب'}</StatusBadge>{' '}
                      <bdi dir="ltr">{part.reference}</bdi> · {part.debtAt ? <bdi>{formatUiDate(part.debtAt,{year:'numeric',month:'2-digit',day:'2-digit'})}</bdi> : 'تاريخ غير متاح'}
                    </span>
                    <span className="font-bold"><Money minor={part.allocateInMinorUnits} /> <span className="text-xs font-normal text-nw-muted">يتبقى <Money minor={part.remainingAfterInMinorUnits} /></span></span>
                  </li>
                ))}
              </ul>
            </div>
          )}
          {error && <p role="alert" className="sm:col-span-2 m-0 whitespace-pre-line rounded-xl bg-nw-bad-bg p-3 text-sm text-nw-bad">{error}</p>}
          <div className="sm:col-span-2 flex flex-wrap gap-2">
            <UiButton onClick={() => void runPreview()} disabled={busy}>معاينة التوزيع</UiButton>
            <UiButton type="submit" variant="accent" disabled={busy || !previewIsCurrent || Boolean(preview?.exceedsBalance)}>
