            />
          </div>

          {/* Supplier Invoice Date */}
          <div className="space-y-1">
            <label className="text-[11px] font-bold text-nw-muted">تاريخ فاتورة المورد</label>
            <input aria-label="تاريخ فاتورة المورد"
