                  min="0"
                  step="0.001"
                  value={taxJod}
                  onChange={(e) => setTaxJod(Math.max(0, Number(e.target.value) || 0))}
                  className="w-full bg-nw-bg border border-nw-border rounded-xl px-2 py-1 text-xs font-bold text-nw-text text-center"
                />
              </div>
            </div>

            <div className="bg-nw-bg border border-nw-border p-2.5 rounded-xl flex items-center justify-between">
              <span className="font-extrabold text-nw-text">صافي المباشر المستحق للمورد:</span>
              <span className="font-extrabold text-nw-ok text-sm">
                {formatJod(grandTotalJod)} {CURRENCY}
              </span>
            </div>
          </div>

          {/* Payment Method & Paid Amount */}
          <div className="space-y-2 bg-nw-bg p-3 rounded-xl border border-nw-border">
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-nw-muted">طريقة الدفع للمورد</label>
              <div className="grid grid-cols-2 gap-1 text-[10px] font-bold">
                <UiButton variant="plain"
                  type="button"
                  onClick={() => setPaymentMethod('cash')}
                  className={`py-1.5 rounded-lg border transition ${
                    paymentMethod === 'cash'
                      ? 'bg-nw-ok-bg text-nw-text border-nw-border shadow'
                      : 'bg-nw-surface border-nw-border text-nw-muted'
                  }`}
                >
                  نقدي (Cash)
                </UiButton>
                <UiButton variant="plain"
                  type="button"
                  onClick={() => setPaymentMethod('cliq')}
                  className={`py-1.5 rounded-lg border transition ${
                    paymentMethod === 'cliq'
                      ? 'bg-nw-info-bg text-nw-text border-nw-border shadow'
                      : 'bg-nw-surface border-nw-border text-nw-muted'
                  }`}
                >
                  CliQ / تحويل
                </UiButton>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div>
                <label className="text-[10px] font-bold text-nw-muted">المبلغ المدفوع الآن ({CURRENCY})</label>
                <input inputMode="decimal" enterKeyHint="next" aria-label="المبلغ المدفوع الآن ( )"
                  type="number"
                  min="0"
                  max={grandTotalJod}
                  step="0.001"
                  value={amountPaidJod}
                  onChange={(e) => setAmountPaidJod(Math.max(0, Number(e.target.value) || 0))}
                  className="w-full bg-nw-surface border border-nw-border rounded-xl px-2 py-1.5 text-xs font-bold text-nw-ok text-center"
                />
                <div className="mt-1 flex items-center gap-1">
                  <UiButton variant="plain"
                    type="button"
                    onClick={() => setAmountPaidJod(grandTotalJod)}
                    className="rounded-lg bg-nw-ok-bg px-2 py-1 text-[9px] font-bold text-nw-ok h-auto min-h-11 min-w-0 whitespace-normal"
                  >
                    دفع كامل
                  </UiButton>
                  <UiButton variant="plain"
                    type="button"
                    onClick={() => setAmountPaidJod(0)}
                    className="rounded-lg bg-nw-surface-2 px-2 py-1 text-[9px] font-bold text-nw-text h-auto min-h-11 min-w-0 whitespace-normal"
                  >
                    بدون دفعة الآن
                  </UiButton>
                </div>
              </div>

              <div>
                <label className="text-[10px] font-bold text-nw-muted">رقم الحوالة/المرجع</label>
                <input aria-label="رقم المرجع اختياري"
                  type="text"
                  value={paymentReference}
                  onChange={(e) => setPaymentReference(e.target.value)}
                  placeholder="رقم المرجع اختياري"
                  className="w-full bg-nw-surface border border-nw-border rounded-xl px-2 py-1.5 text-xs text-nw-text"
                />
              </div>
            </div>

            <div className="flex items-center justify-between gap-2 text-[11px] pt-1 border-t border-nw-border">
              <span className="text-nw-muted font-bold">
                المتبقي يُسجل تلقائياً كذمة للمورد:
              </span>
              <span className={`font-extrabold ${amountDueJod > 0 ? 'text-nw-bad' : 'text-nw-ok'}`}>
                {formatJod(amountDueJod)} {CURRENCY}
              </span>
            </div>
          </div>
        </div>

        {/* Notes */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
          <input aria-label="ملاحظات عامة على الشحنة..."
            type="text"
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            placeholder="ملاحظات عامة على الشحنة..."
            className="w-full bg-nw-bg border border-nw-border rounded-xl px-3 py-1.5 text-xs text-nw-text"
          />
          <input aria-label="ملاحظات إدارية داخلية (غير مطبوعة)..."
            type="text"
            value={internalNotes}
            onChange={(e) => setInternalNotes(e.target.value)}
            placeholder="ملاحظات إدارية داخلية (غير مطبوعة)..."
            className="w-full bg-nw-bg border border-nw-border rounded-xl px-3 py-1.5 text-xs text-nw-text"
          />
        </div>
          </div>
        </details>
      </Card>

      {drawer.warningNode}
      {/* Main Action Button */}
      <div className="pt-2 flex items-center justify-end gap-2 border-t border-nw-border">
        <UiButton variant="plain"
          type="button"
          onClick={onClose}
          disabled={isSubmitting}
          className="bg-nw-surface-2 text-nw-text border border-nw-border px-4 py-2.5 rounded-xl font-bold hover:bg-nw-surface-2 transition h-auto min-h-11 min-w-0 whitespace-normal"
        >
          إلغاء
        </UiButton>

        <UiButton variant="plain"
          type="button"
          onClick={handleSubmitReceipt}
          disabled={isSubmitting || editingProductId!==null || items.length === 0 || legacyReplayResolution !== null}
          className="bg-nw-accent text-nw-on-accent font-extrabold px-6 py-2.5 rounded-xl shadow-lg shadow-nw-border transition flex items-center gap-2 text-xs disabled:opacity-50 h-auto min-h-11 min-w-0 whitespace-normal"
        >
          {isSubmitting ? (
            <>
              <Loader2 className="w-4 h-4 animate-spin text-nw-text" />
              <span>جاري حفظ سند الاستلام وتحديث المخزون...</span>
            </>
          ) : legacyReplayResolution ? (
            <>
              <AlertCircle className="w-4 h-4 text-nw-text" />
              <span>راجع السند الموجود أولًا</span>
            </>
          ) : (
            <>
              <PackageCheck className="w-4 h-4 text-nw-text" />
              <span>حفظ واستلام البضاعة</span>
            </>
          )}
        </UiButton>
      </div>

      {editingProductId&&<ReceivingProductPriceEditor productId={editingProductId} onClose={()=>setEditingProductId(null)} onSavedOrClosed={()=>void refreshEditedSaleQuote(editingProductId)}/>}
      <CreateSupplierModal
        isOpen={showAddSupplierModal}
        onClose={() => setShowAddSupplierModal(false)}
        onSuccess={handleSupplierCreated}
      />
    </FormFields>
  );
};

src/features/expenses/ExpenseFormModal.t.beforeText:
import React, { useState } from 'react';
import { AlertTriangle, Banknote, Smartphone } from 'lucide-react';
import {
  useAppStoreActions,
  useAppStoreSelector,
} from '../../stores/useAppStore';
import {FormFields, UiButton} from '../../components/ui';
import { useDrawerShortfallConfirm } from '../../hooks/useDrawerShortfallConfirm';

interface ExpenseFormModalProps {
  onClose: () => void;
}

const EXPENSE_CATEGORIES = [
  'إيجار',
  'كهرباء وماء',
  'رواتب ومكافآت',
  'تسويق وإعلانات',
  'صيانة',
  'نقل ومحروقات',
  'مصروفات أخرى',
];

export const ExpenseFormModal: React.FC<ExpenseFormModalProps> = ({
  onClose,
}) => {
  const currentShift = useAppStoreSelector((state) => state.currentShift);
  const drawer = useDrawerShortfallConfirm();
  const { addExpense, setActiveTab } = useAppStoreActions();
  const [category, setCategory] = useState(EXPENSE_CATEGORIES[0]);
  const [amount, setAmount] = useState('');
  const [description, setDescription] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'cliq'>('cash');
  const [referenceNumber, setReferenceNumber] = useState('');
  const [isSaving, setIsSaving] = useState(false);

  const numericAmount = Number(amount);
  const isValid =
    Boolean(currentShift) &&
    Number.isFinite(numericAmount) &&
    numericAmount > 0 &&
    description.trim().length >= 2 &&
    (paymentMethod !== 'cliq' || referenceNumber.trim().length > 0);

  if (!currentShift) {
    return (
      <FormFields className="space-y-4 text-center text-xs nw-batch4-fields">
        <div className="rounded-2xl border border-nw-border bg-nw-warn-bg p-5">
          <AlertTriangle className="mx-auto mb-2 h-8 w-8 text-nw-warn" />
          <h3 className="font-black text-nw-warn">افتح وردية الصندوق أولًا</h3>
          <p className="mt-1 leading-5 text-nw-muted">
            كل مصروف يجب أن يرتبط بالوردية المفتوحة حتى تبقى حركة الكاش وCliQ
            قابلة للمراجعة.
          </p>
        </div>
        <UiButton variant="primary"
          type="button"
          onClick={() => {
            onClose();
            setActiveTab('shifts');
          }}
          className="w-full text-xs"
        >
          الانتقال إلى الورديات
        </UiButton>
      </FormFields>
    );
  }

  const handleSubmit = async () => {
    if (!isValid || isSaving) return;
    if (!drawer.confirmCash(numericAmount, paymentMethod === 'cash', currentShift.branchId)) return;
    setIsSaving(true);
    try {
      const success = await addExpense(
        category,
        numericAmount,
        description.trim(),
        paymentMethod,
        referenceNumber
      );

      if (success) onClose();

    } finally {
      setIsSaving(false);
    }
  };

  return (
    <FormFields aria-busy={isSaving} className="nw-batch4-fields space-y-4 text-sm text-nw-text">
      <div className="rounded-xl border border-nw-border bg-nw-ok-bg px-3 py-2 text-nw-ok">
        سيرتبط المصروف بالوردية <b>{currentShift.shiftNumber}</b> تلقائيًا.
      </div>

      <div>
        <label htmlFor="expense-category" className="mb-1 block font-bold text-nw-muted">فئة المصروف</label>
        <select
          id="expense-category"
          value={category}
          onChange={(event) => setCategory(event.target.value)}
          className="w-full rounded-xl border border-nw-border bg-nw-surface-2 p-2.5 text-nw-text"
        >
          {EXPENSE_CATEGORIES.map((item) => (
            <option key={item} value={item}>
              {item}
            </option>
          ))}
        </select>
      </div>

      <div>
        <label htmlFor="expense-amount" className="mb-1 block font-bold text-nw-muted">المبلغ (د.أ) *</label>
        <input inputMode="decimal" enterKeyHint="next"
          id="expense-amount"
          type="number"
          min="0.001"
          step="0.001"
          value={amount}
          onChange={(event) => setAmount(event.target.value)}
          placeholder="0.000"
          className="w-full rounded-xl border border-nw-border bg-nw-surface-2 p-2.5 font-bold text-nw-warn"
        />
      </div>

      <div>
        <label className="mb-1 block font-bold text-nw-muted">طريقة الدفع *</label>
        <div className="grid grid-cols-2 gap-2">
          {([
            ['cash', 'كاش', Banknote],
            ['cliq', 'CliQ', Smartphone],
          ] as const).map(([value, label, Icon]) => (
            <UiButton variant="plain"
              aria-pressed={paymentMethod === value}
              key={value}
              type="button"
              onClick={() => setPaymentMethod(value)}
              className={`flex items-center justify-center gap-2 rounded-xl border p-2.5 font-black transition ${
                paymentMethod === value
                  ? 'border-nw-border bg-nw-ok-bg text-nw-ok'
                  : 'border-nw-border bg-nw-surface-2 text-nw-muted'
              }`}
            >
              <Icon className="h-4 w-4" />
              {label}
            </UiButton>
          ))}
        </div>
      </div>

      {paymentMethod === 'cliq' && (
        <div>
          <label htmlFor="expense-reference" className="mb-1 block font-bold text-nw-muted">
            رقم مرجع CliQ *
          </label>
          <input
            id="expense-reference"
            type="text"
            value={referenceNumber}
            onChange={(event) => setReferenceNumber(event.target.value)}
            placeholder="رقم الحركة أو المرجع"
            className="w-full rounded-xl border border-nw-border bg-nw-surface-2 p-2.5 text-nw-text"
          />
        </div>
      )}

      <div>
        <label htmlFor="expense-description" className="mb-1 block font-bold text-nw-muted">البيان / الوصف *</label>
        <input
          id="expense-description"
          type="text"
          value={description}
          onChange={(event) => setDescription(event.target.value)}
          placeholder="مثال: فاتورة كهرباء الفرع"
          className="w-full rounded-xl border border-nw-border bg-nw-surface-2 p-2.5 text-nw-text"
        />
      </div>

      {drawer.warningNode}
      <UiButton variant="accent"
        type="button"
        disabled={!isValid || isSaving}
        onClick={() => void handleSubmit()}
        className="sticky bottom-0 z-10 w-full text-sm shadow-lg"
      >
        {isSaving ? 'جاري تسجيل المصروف...' : 'اعتماد وتسجيل المصروف'}
      </UiButton>
    </FormFields>
  );
};

src/features/more/ParcelConfigurationMod.beforeText:
import {useAppStore} from '../../stores/useAppStore';
import {OffParcelFeatureControl} from './OffParcelFeatureControl';
import {FormFields,UiButton,formatJod} from '../../components/ui';
import {useEffect, useRef, useState, type FormEvent} from 'react';
import {useAuthStore} from '../../stores/useAuthStore';
import {fetchAdminProductById} from '../../services/supabase/products.service';
import {unsafeLiteParcelPrice,PARCEL_DEFINITION_MESSAGE} from '../../../customer-web/src/utils/saleUnitLabels';
import {filterParcelFamilies} from '../../utils/parcelFamilySearch';
import {fetchParcelConfigurationContext, saveParcelConfiguration, setParcelFeatureState,
  type ParcelConfigurationContext, type ParcelConfigurationInput, type ParcelFeatureState} from '../../services/supabase/parcelConfiguration.service';

const inputClass = 'mt-1 w-full rounded-lg border border-nw-border bg-nw-surface p-2 text-sm';
const labels = {OFF:'متوقفة',OWNER_PILOT:'تجربة المالك فقط',ENABLED:'مفعّلة للجميع'};
const flavorFamilies = (data: ParcelConfigurationContext) => data.products.filter(p =>
  p.isFlavorMaster && p.components.some(c => c.productId !== p.familyProductId)
  && p.configuration?.composition_mode!=='single_sku');
export function ParcelConfigurationModal({initialFamilyProductId,operatingMode='full',modeVerified=true}:{initialFamilyProductId?:string;operatingMode?:'full'|'sales-only';modeVerified?:boolean}) {
  const {roleName:role} = useAuthStore();
  const salesOnly=operatingMode==='sales-only';
  const {products:catalogProducts}=useAppStore();
  const contentUnit=(familyId:string)=>catalogProducts.find(product=>product.id===familyId)?.unit||'باكيت';
  const authorization=useRef({role,operatingMode,modeVerified});
  authorization.current={role,operatingMode,modeVerified};
  const [context,setContext] = useState<ParcelConfigurationContext | null>(null);
  const [form,setForm] = useState<ParcelConfigurationInput | null>(null);
  const [nextState,setNextState] = useState<ParcelFeatureState>('OFF');
  const [confirm,setConfirm] = useState(false);
  const [busy,setBusy] = useState(false);
  const [message,setMessage] = useState('');
  const [error,setError] = useState('');
  const [uncertain,setUncertain] = useState(false);
  const [familySearch,setFamilySearch] = useState('');
  const select = (data: ParcelConfigurationContext, id: string) => {
    const candidates = flavorFamilies(data);
    const p = candidates.find(product => product.familyProductId === id) ?? candidates[0];
    setForm(p ? {familyProductId:p.familyProductId,mode:'configurable_mix',
      active:p.configuration?.is_active ?? false, units:p.unitsPerParcel,
      allowed:p.configuration ? [...p.allowedProductIds] : p.isFlavorMaster ? [] : [id]} : null);
  };
  useEffect(() => {
    if (role !== 'owner') return;
    let active = true;
    void fetchParcelConfigurationContext().then(data => {if (active) {setContext(data);setNextState(data.featureState);select(data,initialFamilyProductId ?? data.products[0]?.familyProductId ?? '');}})
      .catch(reason => {if (active) setError(reason instanceof Error ? reason.message : 'تعذر تحميل الإعداد.');});
    return () => {active=false;};
  },[role,initialFamilyProductId]);
  const reload = async () => {
    setBusy(true);setError('');
    try {const data=await fetchParcelConfigurationContext();setContext(data);setNextState(data.featureState);
      select(data,form?.familyProductId ?? data.products[0]?.familyProductId ?? '');setUncertain(false);setConfirm(false);}
    catch (reason) {setError(reason instanceof Error ? reason.message : 'تعذر تحميل الإعداد.');}
    finally {setBusy(false);}
  };
  const save = async (event: FormEvent) => {
    event.preventDefault();if (!context || !form || busy || uncertain) return;
    const p=context.products.find(product=>product.familyProductId===form.familyProductId);if (!p) return;
    setBusy(true);setError('');setMessage('');
    try {
      if(!modeVerified)throw new Error('أعد قراءة وضع التشغيل قبل حفظ إعداد الطرد.');
      if(salesOnly){
        const fresh=await fetchAdminProductById(form.familyProductId);
        if(!fresh||authorization.current.role!=='owner'||!authorization.current.modeVerified||authorization.current.operatingMode!==operatingMode)throw new Error('تعذر التحقق من وضع التشغيل وتعريف المنتج؛ أعد التحميل.');
        if(form.units!==fresh.unitsPerSalePackage)throw new Error('عدّل عدد الطرد من نموذج المنتج أولاً، ثم أعد تحميل إعداد النكهات.');
        const sameUnit=fresh.baseUnitId===fresh.saleUnitId||fresh.unit?.trim()===fresh.salePackage?.trim();
        if(form.active&&form.units>1&&(sameUnit||unsafeLiteParcelPrice(true,form.units,fresh.salePackagePrice,fresh.retailPrice)))throw new Error(PARCEL_DEFINITION_MESSAGE);
      }
      await saveParcelConfiguration(form,p);const data=await fetchParcelConfigurationContext();setContext(data);select(data,form.familyProductId);setMessage('تم حفظ إعداد الطرد.');}
    catch (reason) {setUncertain(true);setError(reason instanceof Error ? reason.message : 'تعذر تأكيد الحفظ؛ أعد تحميل الإعداد.');}
    finally {setBusy(false);}
  };
  const changeState = async () => {
    if (!confirm || !context || busy || uncertain || nextState===context.featureState) return;
    setBusy(true);setError('');setMessage('');
    try {await setParcelFeatureState(nextState);const data=await fetchParcelConfigurationContext();setContext(data);setNextState(data.featureState);setConfirm(false);setMessage('تم تغيير حالة الميزة.');}
    catch (reason) {setUncertain(true);setError(reason instanceof Error ? reason.message : 'تعذر تأكيد تغيير الحالة؛ أعد التحميل.');}
    finally {setBusy(false);}
  };
  const disableLegacy = async (product:ParcelConfigurationContext['products'][number]) => {
    if(busy||uncertain||product.configuration?.composition_mode!=='single_sku'||!product.configuration.is_active)return;
    setBusy(true);setError('');setMessage('');
    try{
      await saveParcelConfiguration({familyProductId:product.familyProductId,mode:'single_sku',active:false,
        units:product.unitsPerParcel,allowed:[...product.allowedProductIds]},product);
      const data=await fetchParcelConfigurationContext();setContext(data);select(data,form?.familyProductId??'');setMessage('تم إيقاف الإعداد القديم؛ بيانات المبيعات السابقة محفوظة.');
    }catch(reason){setUncertain(true);setError(reason instanceof Error?reason.message:'تعذر تأكيد الإيقاف؛ أعد تحميل الإعداد.');}
    finally{setBusy(false);}
  };
  if (role !== 'owner') return <p role="alert">إعداد الطرود متاح للمالك فقط.</p>;
