];
const PAGE_SIZE = 25;

const PAYMENT_LABELS: Record<string, string> = { cash: 'كاش', cliq: 'CliQ', cash_on_delivery: 'كاش عند الاستلام', debt: 'دين', mixed: 'مختلط', card: 'بطاقة', bank_transfer: 'تحويل بنكي' };

export const OperationalOrderCard: React.FC<{
